package com.example.helpdesk.service;
import com.example.helpdesk.model.*; import com.example.helpdesk.repo.*; import org.junit.jupiter.api.Test; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.junit.jupiter.api.extension.ExtendWith; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class TicketServiceTest { @Mock TicketRepository tickets; @Mock UserRepository users; @Mock TicketHistoryRepository history;
 @Test void resolvedTicketRequiresNotes(){TicketService service=new TicketService(tickets,users,history);Ticket ticket=new Ticket();when(tickets.findById(1L)).thenReturn(java.util.Optional.of(ticket));assertThrows(IllegalArgumentException.class,()->service.updateStatus(1L,TicketStatus.RESOLVED,"", "tech"));}
 @Test void employeeCanCreateOpenTicket(){TicketService service=new TicketService(tickets,users,history);User employee=new User("e","hash","Employee",Role.EMPLOYEE);when(users.findByUsername("e")).thenReturn(java.util.Optional.of(employee));Ticket input=new Ticket();input.setTitle("Wi-Fi issue");input.setDescription("No connection");input.setCategory(Category.NETWORK);when(tickets.save(input)).thenReturn(input);Ticket result=service.create(input,"e");assertSame(employee,result.getReporter());assertEquals(TicketStatus.OPEN,result.getStatus());verify(history).save(any(TicketHistory.class));}
}
